  const txt = (p, x, y, text, st = {}) => s('text', { x, y, text, 'text-anchor': 'middle', style: Object.assign({ fontSize: '16px', fill: C.ink2 }, st) }, p);
  const gQ = s('g', { style: { opacity: 0, transition: 'opacity .5s' } }, svg);
